async function handleHomeChatStart(btn) {
  // 카카오로 로그인된 상태면 firebaseAuthReady와 무관하게 바로 진행할 수 있습니다.
  if (getKakaoUser()) { showAiChatSetupStep(); return; }

  // 구글 로그인 상태 확인이 아직 끝나지 않았을 수 있어서(특히 접속 직후), 그 확인이
  // 끝날 때까지 살짝 기다렸다가 판단합니다. 이걸 안 하면 실제로는 로그인돼 있는데도
  // "로그인 안 됨"으로 착각해서 버튼이 안 먹히는 것처럼 보일 수 있습니다.
  if (!firebaseAuthReady) {
    const originalText = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = '확인 중…'; }
    await Promise.race([
      firebaseAuthSettled,
      new Promise((r) => setTimeout(r, 4000)) // 너무 오래 걸리면 그냥 진행합니다.
    ]);
    if (btn) { btn.disabled = false; btn.textContent = originalText; }
  }

  const loggedIn = getKakaoUser() || (firebaseReady && firebaseAuthReady && firebaseAuthUser);
  if (!loggedIn) {
    localStorage.setItem('taekilso_pending_chat_start', '1');
    openAuthModal();
    return;
  }
  showAiChatSetupStep();
}

